protected void loadDefaults() {
    super.loadDefaults();
    actions = new ArrayList<Types.ACTIONS>();
    actionsNIL = new ArrayList<Types.ACTIONS>();

    color = Types.WHITE;
    speed = 1;
    is_avatar = true;
    is_disqualified = false;
}

public void postProcess() {

    //Define actions here first.
    if(actions.size()==0)
    {
        actions.add(Types.ACTIONS.ACTION_LEFT);
        actions.add(Types.ACTIONS.ACTION_RIGHT);
        actions.add(Types.ACTIONS.ACTION_DOWN);
        actions.add(Types.ACTIONS.ACTION_UP);
    }

    super.postProcess();

    //A separate array with the same actions, plus NIL.
    for(Types.ACTIONS act : actions)
    {
        actionsNIL.add(act);
    }
    actionsNIL.add(Types.ACTIONS.ACTION_NIL);
}

public class StepBack extends Effect
{
    public boolean pixelPerfect;

    public StepBack(InteractionContent cnt)
    {
        pixelPerfect = false;
        this.parseParameters(cnt);
    }

    @Override
    public void execute(VGDLSprite sprite1, VGDLSprite sprite2, Game game)
    {
	if(sprite1 == null){
	    Logger.getInstance().addMessage(new Message(Message.WARNING, "1st sprite can't be EOS with StepBack interaction."));
	    return;
	}

        if(pixelPerfect && sprite2!=null) //Sprite2 could be Null in an EOS case.
            sprite1.setRect(calculatePixelPerfect(sprite1, sprite2));
        else
            sprite1.setRect(sprite1.lastrect);
    }

}

public class BounceForward extends Effect
{

    public BounceForward(InteractionContent cnt)
    {
        this.parseParameters(cnt);
    }

    @Override
    public void execute(VGDLSprite sprite1, VGDLSprite sprite2, Game game)
    {
        if(sprite1 == null || sprite2 == null){
            Logger.getInstance().addMessage(new Message(Message.WARNING, "Neither the 1st nor 2nd sprite can be EOS with BounceForward interaction."));
            return;
        }

        Vector2d dir = new Vector2d(sprite2.lastDirection());
        dir.normalise();

        if(sprite2.lastDirection().x * sprite2.orientation.x() < 0)
            dir.x *= -1;

        if(sprite2.lastDirection().y * sprite2.orientation.y() < 0)
            dir.y *= -1;

        //Rectangle r = new Rectangle(sprite1.rect);
        sprite1.physics.activeMovement(sprite1, new Direction(dir.x, dir.y), sprite2.speed);
        //sprite1.lastrect = r;
        sprite1.orientation = new Direction(dir.x, dir.y);
        game._updateCollisionDict(sprite1);
    }
}

