public void postProcess()
{
    //Define actions here first.
    if(actions.size()==0)
    {
        actions.add(Types.ACTIONS.ACTION_USE);
        actions.add(Types.ACTIONS.ACTION_LEFT);
        actions.add(Types.ACTIONS.ACTION_RIGHT);
        actions.add(Types.ACTIONS.ACTION_DOWN);
        actions.add(Types.ACTIONS.ACTION_UP);
    }

    super.postProcess();

    stypes = stype.split(",");
    itype = new int[stypes.length];

    for (int i = 0; i < itype.length; i++)
        itype[i] = VGDLRegistry.GetInstance().getRegisteredSpriteValue(stypes[i]);
    if(ammo != null) {
        ammos = ammo.split(",");
        ammoId = new int[ammos.length];
        for (int i = 0; i < ammos.length; i++) {
            ammoId[i] = VGDLRegistry.GetInstance().getRegisteredSpriteValue(ammos[i]);
        }
    }
}

protected void loadDefaults()
{
    super.loadDefaults();
    orientation = Types.DRIGHT.copy();
    draw_arrow = true;
    is_oriented = true;
    rotateInPlace = true;
}

protected void loadDefaults() {
    super.loadDefaults();
    actions = new ArrayList<Types.ACTIONS>();
    actionsNIL = new ArrayList<Types.ACTIONS>();

    color = Types.WHITE;
    speed = 1;
    is_avatar = true;
    is_disqualified = false;
}

public void postProcess() {

    //Define actions here first.
    if(actions.size()==0)
    {
        actions.add(Types.ACTIONS.ACTION_LEFT);
        actions.add(Types.ACTIONS.ACTION_RIGHT);
        actions.add(Types.ACTIONS.ACTION_DOWN);
        actions.add(Types.ACTIONS.ACTION_UP);
    }

    super.postProcess();

    //A separate array with the same actions, plus NIL.
    for(Types.ACTIONS act : actions)
    {
        actionsNIL.add(act);
    }
    actionsNIL.add(Types.ACTIONS.ACTION_NIL);
}

