    		VGDLSprite newSprite = game.addSprite(itype, sprite1.getPosition());
    		transformTo(newSprite, sprite1,  sprite2,  game);
    	}
    }

    protected void transformTo(VGDLSprite newSprite, VGDLSprite sprite1, VGDLSprite sprite2, Game game)
    {
        if(newSprite != null)
        {
            //Orientation
            if(forceOrientation || newSprite.is_oriented && sprite1.is_oriented && newSprite.orientation.equals(Types.DNONE))
            {
                newSprite.orientation = sprite1.orientation;
            }

            //Last position of the avatar.
            newSprite.lastrect =  new Rectangle(sprite1.lastrect.x, sprite1.lastrect.y,
                    sprite1.lastrect.width, sprite1.lastrect.height);

            //Copy resources
            if(sprite1.resources.size() > 0)
            {
                Set<Map.Entry<Integer, Integer>> entries = sprite1.resources.entrySet();
                for(Map.Entry<Integer, Integer> entry : entries)
                {
                    int resType = entry.getKey();
                    int resValue = entry.getValue();
                    newSprite.modifyResource(resType, resValue);
                }
            }


            //Avatar handling.
            boolean transformed = true;
            if(sprite1.is_avatar)
            {
                try{
                    int id = ((MovingAvatar)sprite1).getPlayerID();
                    Player p = game.getAvatar(id).player;
                    double score = game.getAvatar(id).getScore();
                    Types.WINNER win = game.getAvatar(id).getWinState();
                    game.setAvatar((MovingAvatar) newSprite, id);
                    game.getAvatar(id).player = p;
                    game.getAvatar(id).setKeyHandler(Game.ki);
                    game.getAvatar(id).setScore(score);
                    game.getAvatar(id).setWinState(win);
                    game.getAvatar(id).setPlayerID(id);
                    transformed = true;
                }catch (ClassCastException e) {
                    transformed = false; // new sprite is not an avatar, don't kill the current one
                }
            }

            //Health points should be copied too.
            newSprite.healthPoints = sprite1.healthPoints;

            //boolean variable in method call set to true
            //to indicate the sprite was transformed
            game.killSprite(sprite1, transformed);

            if(killSecond && sprite2 != null)
                game.killSprite(sprite2, true);
        }
    }

    @Override
    public ArrayList<String> getEffectSprites(){
    	ArrayList<String> result = new ArrayList<String>();
    	if(stype!=null) result.add(stype);

    	return result;
    }
}

public class BounceForward extends Effect
{

    public BounceForward(InteractionContent cnt)
    {
        this.parseParameters(cnt);
    }

    @Override
    public void execute(VGDLSprite sprite1, VGDLSprite sprite2, Game game)
    {
        if(sprite1 == null || sprite2 == null){
            Logger.getInstance().addMessage(new Message(Message.WARNING, "Neither the 1st nor 2nd sprite can be EOS with BounceForward interaction."));
            return;
        }

        Vector2d dir = new Vector2d(sprite2.lastDirection());
        dir.normalise();

        if(sprite2.lastDirection().x * sprite2.orientation.x() < 0)
            dir.x *= -1;

        if(sprite2.lastDirection().y * sprite2.orientation.y() < 0)
            dir.y *= -1;

        //Rectangle r = new Rectangle(sprite1.rect);
        sprite1.physics.activeMovement(sprite1, new Direction(dir.x, dir.y), sprite2.speed);
        //sprite1.lastrect = r;
        sprite1.orientation = new Direction(dir.x, dir.y);
        game._updateCollisionDict(sprite1);
    }
}

public class UndoAll extends Effect
{
    /**
     * List of sprites that do NOT respond to UndoAll. This list can be specified
     * with sprite string identifiers separated by commas.
     */
    public String notStype;

    //List of IDs of the sprites not affected by UndoAll. ArrayList for efficiency.
    private ArrayList<Integer> notItypes;

    public UndoAll(InteractionContent cnt)
    {
        this.parseParameters(cnt);
        int notItypesArray[] = VGDLRegistry.GetInstance().explode(notStype);
        notItypes = new ArrayList<>();
        for(Integer it : notItypesArray)
            notItypes.add(it);
    }

    @Override
    public void execute(VGDLSprite sprite1, VGDLSprite sprite2, Game game)
    {
        int[] gameSpriteOrder = game.getSpriteOrder();
        int spriteOrderCount = gameSpriteOrder.length;
        for(int i = 0; i < spriteOrderCount; ++i)
        {
            int spriteTypeInt = gameSpriteOrder[i];

            if(notItypes.contains(spriteTypeInt))
                continue;

            Iterator<VGDLSprite> spriteIt = game.getSpriteGroup(spriteTypeInt);
            if(spriteIt != null) while(spriteIt.hasNext())
            {
                VGDLSprite sp = spriteIt.next();
                sp.setRect(sp.lastrect);
            }
        }
    }
}

